const alert = $json.body ?? $json;

const rule = alert.rule ?? {};
const agent = alert.agent ?? {};
const data = alert.data ?? {};

const level = Number(rule.level ?? 0);

let severity = "LOW";
let action = "LOG_ONLY";
let priority = "P4";

if (level >= 12) {
  severity = "CRITICAL";
  action = "IMMEDIATE_SOC_ESCALATION";
  priority = "P1";
} else if (level >= 10) {
  severity = "HIGH";
  action = "SOC_ESCALATION";
  priority = "P2";
} else if (level >= 7) {
  severity = "MEDIUM";
  action = "ANALYST_REVIEW";
  priority = "P3";
}

return {
  json: {
    timestamp: alert.timestamp ?? new Date().toISOString(),

    rule_id: rule.id ?? "N/A",
    rule_level: level,
    description: rule.description ?? "No description",

    severity,
    priority,
    automated_action: action,

    agent_id: agent.id ?? "N/A",
    agent_name: agent.name ?? "Wazuh Manager",

    source_ip: data.srcip ?? data.src_ip ?? "N/A",
    destination_user: data.dstuser ?? data.user ?? "N/A",

    manager: alert.manager?.name ?? "wazuh-manager",

    requires_notification: level >= 7,

    original_event: alert
  }
};
